import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:dairy_ai/features/auth/providers/auth_provider.dart';
import '../models/marketplace_models.dart';
final marketplaceFilterProvider=StateProvider<MarketplaceFilter>((_)=>const MarketplaceFilter());
final marketplaceListingsProvider=AsyncNotifierProvider<MarketplaceListingsNotifier,List<MarketplaceListing>>(MarketplaceListingsNotifier.new);
class MarketplaceListingsNotifier extends AsyncNotifier<List<MarketplaceListing>> {int _offset=0;bool hasMore=true;@override Future<List<MarketplaceListing>> build()=>_fetch(true);Future<List<MarketplaceListing>> _fetch([bool reset=false]) async {final b=(await ref.read(dioProvider).get('/marketplace/listings',queryParameters:{...ref.read(marketplaceFilterProvider).query,'limit':20,'offset':reset?0:_offset})).data as Map<String,dynamic>;final x=(b['data'] as List).map((e)=>MarketplaceListing.fromJson(e as Map<String,dynamic>)).toList();if(reset){_offset=x.length;hasMore=x.length<(b['total'] as int? ?? 0);return _sort(x);} _offset+=x.length;hasMore=x.isNotEmpty;return [...state.value??[],..._sort(x)];}List<MarketplaceListing> _sort(List<MarketplaceListing>x){final s=ref.read(marketplaceFilterProvider).sort;x.sort((a,b)=>s=='price_low'?a.price.compareTo(b.price):s=='price_high'?b.price.compareTo(a.price):s=='most_viewed'?b.viewsCount.compareTo(a.viewsCount):b.createdAt.compareTo(a.createdAt));return x;}Future<void> refresh()async{state=const AsyncLoading();state=await AsyncValue.guard(()=>_fetch(true));}Future<void> toggleFavorite(MarketplaceListing x)async{final old=state.value??[];state=AsyncData([for(final a in old)a.id==x.id?a.copyWith(isFavorited:!a.isFavorited):a]);try{await ref.read(dioProvider).post('/marketplace/listings/${x.id}/favorite');}catch(_){state=AsyncData(old);rethrow;}}}
final marketplaceDetailProvider=FutureProvider.family<MarketplaceListing,String>((ref,id)async{final b=(await ref.read(dioProvider).get('/marketplace/listings/$id')).data as Map<String,dynamic>;return MarketplaceListing.fromJson(b['data'] as Map<String,dynamic>);});
